import { test, expect } from '@playwright/test'
import { mkdirSync, writeFileSync } from 'node:fs'

/**
 * 8443 参考站逐像素 E2E：对比 http://localhost:8443/ 与 nginx 部署的 test 构建（VITE_UI_REF8443）。
 * 阈值：单像素 RGB 差分和 > 24 视为不同；要求差异比例 0%（100% 还原）。
 */

const REF = process.env.REF8443_URL ?? 'http://localhost:8443/'
const OUT = 'artifacts/ref8443-diff'
const MAX_RATIO = Number(process.env.REF8443_MAX_DIFF_RATIO ?? '0')
const DELTA = Number(process.env.REF8443_PIXEL_DELTA ?? '24')

mkdirSync(OUT, { recursive: true })

test.beforeEach(async ({ page }) => {
  await page.route(/font|woff2?|\.ttf|\.otf|static\.figma\.com/i, route => route.abort()).catch(() => {})
})

async function ready(page: import('@playwright/test').Page) {
  await page.waitForSelector('.app-header', { timeout: 30_000 })
  await page.waitForTimeout(800)
}

async function screenshotB64(page: import('@playwright/test').Page) {
  const buf = await page.screenshot({ animations: 'disabled', timeout: 120_000 })
  return buf.toString('base64')
}

async function comparePixels(refB64: string, mineB64: string, page: import('@playwright/test').Page) {
  return page.evaluate(
    ({ ref, mine, delta }) => {
      const load = (src: string) =>
        new Promise<HTMLImageElement>((resolve, reject) => {
          const img = new Image()
          img.onload = () => resolve(img)
          img.onerror = reject
          img.src = src
        })
      return Promise.all([load(ref), load(mine)]).then(([refImg, mineImg]) => {
        const width = Math.min(refImg.width, mineImg.width)
        const height = Math.min(refImg.height, mineImg.height)
        const canvas = document.createElement('canvas')
        canvas.width = width
        canvas.height = height
        const ctx = canvas.getContext('2d')!
        const read = (img: HTMLImageElement) => {
          const c = document.createElement('canvas')
          c.width = width
          c.height = height
          c.getContext('2d')!.drawImage(img, 0, 0)
          return c.getContext('2d')!.getImageData(0, 0, width, height).data
        }
        const a = read(refImg)
        const b = read(mineImg)
        let changed = 0
        for (let i = 0; i < a.length; i += 4) {
          const d =
            Math.abs(a[i] - b[i]) + Math.abs(a[i + 1] - b[i + 1]) + Math.abs(a[i + 2] - b[i + 2])
          if (d > delta) changed++
        }
        const total = width * height
        return { width, height, total, changed, ratio: total ? changed / total : 0 }
      })
    },
    { ref: `data:image/png;base64,${refB64}`, mine: `data:image/png;base64,${mineB64}`, delta: DELTA },
  )
}

const scenes: {
  name: string
  ref: (page: import('@playwright/test').Page) => Promise<void>
  mine: (page: import('@playwright/test').Page, baseURL: string) => Promise<void>
}[] = [
  {
    name: '历史记录-汛前',
    ref: async page => {
      await page.goto(REF, { waitUntil: 'domcontentloaded' })
      await ready(page)
    },
    mine: async (page, baseURL) => {
      await page.goto(`${baseURL}/#/pages/history/index`, { waitUntil: 'domcontentloaded' })
      await page.waitForSelector('.ui-ref8443', { timeout: 30_000 })
      await ready(page)
    },
  },
  {
    name: '历史记录-求援筛选',
    ref: async page => {
      await page.goto(REF, { waitUntil: 'domcontentloaded' })
      await ready(page)
      await page.getByRole('button', { name: '汛中巡检' }).click()
      await page.getByRole('button', { name: '求援工单 (2)' }).click()
      await page.waitForTimeout(500)
    },
    mine: async (page, baseURL) => {
      await page.goto(`${baseURL}/#/pages/history/index`, { waitUntil: 'domcontentloaded' })
      await page.waitForSelector('.ui-ref8443', { timeout: 30_000 })
      await ready(page)
      await page.getByText('汛中巡检').click()
      await page.getByText('求援工单 (2)').click()
      await page.waitForTimeout(500)
    },
  },
  {
    name: '汛前检查',
    ref: async page => {
      await page.goto(REF, { waitUntil: 'domcontentloaded' })
      await ready(page)
      await page.getByRole('button', { name: '继续填报' }).first().click()
      await page.waitForSelector('.form-page', { timeout: 20_000 })
      await page.waitForTimeout(600)
    },
    mine: async (page, baseURL) => {
      await page.goto(`${baseURL}/#/pages/inspection/index?kind=pre`, { waitUntil: 'domcontentloaded' })
      await page.waitForSelector('.ui-ref8443 .form-page', { timeout: 30_000 })
      await ready(page)
    },
  },
  {
    name: '汛中巡检',
    ref: async page => {
      await page.goto(REF, { waitUntil: 'domcontentloaded' })
      await ready(page)
      await page.getByRole('button', { name: '汛中巡检' }).click()
      await page.getByRole('button', { name: '继续填报' }).first().click()
      await page.waitForSelector('.form-page', { timeout: 20_000 })
      await page.waitForTimeout(600)
    },
    mine: async (page, baseURL) => {
      await page.goto(`${baseURL}/#/pages/inspection/index?kind=mid`, { waitUntil: 'domcontentloaded' })
      await page.waitForSelector('.ui-ref8443 .form-page', { timeout: 30_000 })
      await ready(page)
    },
  },
  {
    name: '求援工单',
    ref: async page => {
      await page.goto(REF, { waitUntil: 'domcontentloaded' })
      await ready(page)
      await page.getByRole('button', { name: '汛中巡检' }).click()
      await page.getByRole('button', { name: '继续填报' }).first().click()
      await page.waitForSelector('.floating-rescue', { timeout: 20_000 })
      await page.getByRole('button', { name: '紧急求救' }).click()
      await page.waitForSelector('.form-page', { timeout: 20_000 })
      await page.waitForTimeout(600)
    },
    mine: async (page, baseURL) => {
      await page.goto(`${baseURL}/#/pages/rescue/index`, { waitUntil: 'domcontentloaded' })
      await page.waitForSelector('.ui-ref8443 .form-page', { timeout: 30_000 })
      await ready(page)
    },
  },
]

for (const scene of scenes) {
  test(`8443 像素一致 · ${scene.name}`, async ({ browser, baseURL }) => {
    test.skip(!baseURL, '需要 E2E_BASE_URL / playwright baseURL（nginx 8095）')

    const ctx = await browser.newContext({ viewport: { width: 390, height: 844 } })
    const refPage = await ctx.newPage()
    const minePage = await ctx.newPage()

    await scene.ref(refPage)
    await scene.mine(minePage, baseURL!)

    const refB64 = await screenshotB64(refPage)
    const mineB64 = await screenshotB64(minePage)
    writeFileSync(`${OUT}/${scene.name}-ref.png`, Buffer.from(refB64, 'base64'))
    writeFileSync(`${OUT}/${scene.name}-mine.png`, Buffer.from(mineB64, 'base64'))

    const cmp = await comparePixels(refB64, mineB64, minePage)
    await ctx.close()

    const ratioPct = +(cmp.ratio * 100).toFixed(4)
    expect(
      cmp.ratio,
      `${scene.name}: 差异 ${cmp.changed}/${cmp.total} = ${ratioPct}%`,
    ).toBeLessThanOrEqual(MAX_RATIO)
  })
}

